<asy>
// made by SirCalcsALot

size(200);
dotfactor = 10;

pair p1 = (-28,0);
pair p2 = (-111,213);
draw(p1--p2,linewidth(1));

pair p3 = (-160,0);
pair p4 = (-244,213);
draw(p3--p4,linewidth(1));

pair p5 = (-316,0);
